BEGIN;
-- Invoked inside a staging-only transaction which ALWAYS ROLLS BACK.
-- Synthetic refund-policy fixture: never persist this setup outside the test transaction.
insert into hunkart_cancel.settings(id,enabled,full_refund_policy_accepted) values(true,true,true) on conflict(id) do update set enabled=true,full_refund_policy_accepted=true;
create temp table hd_test_results(name text,passed boolean);
create function pg_temp.check_ok(v boolean,n text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',n;end if;insert into hd_test_results values(n,true);end $$;
create function pg_temp.denied(q text,n text) returns void language plpgsql as $$declare failed boolean:=false;begin begin execute q;exception when others then failed:=true;end;if not failed then raise exception 'FAILED: %',n;end if;insert into hd_test_results values(n,true);end $$;
do $$
declare k uuid:=gen_random_uuid();c uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();rid uuid:=gen_random_uuid();rid2 uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();pid uuid:=gen_random_uuid();oid uuid:=gen_random_uuid();oid2 uuid:=gen_random_uuid();oid3 uuid:=gen_random_uuid();f uuid;notice_id uuid;old_token uuid;r jsonb;
begin
 insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data) select x,'authenticated','authenticated','hd-'||x||'@example.invalid','{}','{}' from unnest(array[k,c,a,b])x;
 insert into public.customers(id,full_name) values(c,'Synthetic only') on conflict(id) do nothing;
 insert into public.shops(id,name,location_lat,location_lng) values(sid,'Synthetic test shop',21.91,85.23);
 insert into public.shopkeepers(user_id,shop_id,active) values(k,sid,true);
 insert into public.products(id,name,shop_id) values(pid,'Synthetic item',sid);
 insert into public.delivery_boys(id,user_id,full_name,is_active) values(rid,a,'Synthetic rider A',true),(rid2,b,'Synthetic rider B',true);
 insert into public.orders(id,order_number,customer_id,status,payment_status,payment_id,subtotal,total,shop_id,customer_name,phone,address,area) values(oid,'HD-TEST-'||oid,c,'new','paid','pay_SyntheticA',100,100,sid,'Synthetic customer','0000000000','Synthetic address','Synthetic area'),(oid2,'HD-TEST-'||oid2,c,'new','paid','pay_SyntheticB',100,100,sid,'Synthetic customer','0000000000','Synthetic address','Synthetic area');
 insert into public.order_items(order_id,product_id,product_name,variant,variant_label,qty,unit_price,line_total) values(oid,pid,'Synthetic item','full','Full',1,100,100),(oid2,pid,'Synthetic item','full','Full',1,100,100);
 perform set_config('request.jwt.claim.sub',k::text,true);
 perform pg_temp.denied(format('select public.hd_accept_shop_order(%L)',oid),'feature disabled');
 update hunkart_dispatch.settings set enabled=true where singleton=true;
 perform pg_temp.denied(format('select public.hd_accept_shop_order(%L)',oid),'three minute window preserved');
update hunkart_dispatch.staff_notification_settings set enabled=true where singleton=true;
perform hunkart_dispatch.enqueue_staff_notifications();
perform pg_temp.check_ok(not exists(select 1 from hunkart_dispatch.staff_notification_outbox where order_id=oid),'staff alert waits for cancellation window');
 update public.orders set customer_cancel_until=now()-interval '1 second' where id in (oid,oid2);
 perform set_config('request.jwt.claim.sub',c::text,true);
 perform pg_temp.denied(format('select public.hd_accept_shop_order(%L)',oid),'customer cannot accept');
 perform set_config('request.jwt.claim.sub',k::text,true);
 update public.shopkeepers set active=false where user_id=k;
 perform pg_temp.denied(format('select public.hd_accept_shop_order(%L)',oid),'inactive keeper denied');
 update public.shopkeepers set active=true where user_id=k;
 update public.orders set payment_status='pending' where id=oid;
 perform pg_temp.denied(format('select public.hd_accept_shop_order(%L)',oid),'unpaid order denied');
 update public.orders set payment_status='paid' where id=oid;
 perform pg_temp.check_ok(public.hd_staff_profile('keeper')->'shop'->>'id'=sid::text,'keeper own profile');
 perform pg_temp.check_ok(jsonb_array_length(public.hd_staff_profile('keeper')->'products')=1,'keeper own products');
 perform pg_temp.check_ok(public.hd_staff_profile('rider') is null,'keeper cannot read rider profile');
 perform pg_temp.check_ok(jsonb_array_length(public.hd_my_shop_orders())=2,'keeper sees own paid pending orders');
 
perform hunkart_dispatch.enqueue_staff_notifications();perform hunkart_dispatch.enqueue_staff_notifications();
perform pg_temp.check_ok((select count(*)=1 from hunkart_dispatch.staff_notification_outbox where order_id=oid and recipient_id=k),'one shop alert despite repeat enqueue');
perform pg_temp.check_ok(not exists(select 1 from hunkart_dispatch.staff_notification_outbox where order_id=oid and recipient_id<>k),'no unrelated recipient');
perform set_config('request.jwt.claims','{"role":"authenticated"}',true);
perform pg_temp.denied('select public.hd_claim_staff_notifications()','customer cannot claim alerts');
perform set_config('request.jwt.claims','{"role":"service_role"}',true);
r:=public.hd_claim_staff_notifications();
select id,lease_token into notice_id,old_token from hunkart_dispatch.staff_notification_outbox where order_id=oid;
perform pg_temp.check_ok(jsonb_array_length(r)=2,'eligible shop alerts claimed');
perform pg_temp.check_ok(jsonb_array_length(public.hd_claim_staff_notifications())=0,'active lease prevents duplicate');
r:=public.hd_staff_notification_delivery(notice_id,old_token);
perform pg_temp.check_ok(r->'payload'->>'event'='shop_order_ready' and not(r->'payload'?'phone') and not(r->'payload'?'address'),'staff payload privacy');
perform pg_temp.check_ok(jsonb_array_length(r->'subscriptions')=0,'no invented device');
perform public.hd_ack_staff_notification(notice_id,gen_random_uuid(),'sent');
perform pg_temp.check_ok((select status='sending' from hunkart_dispatch.staff_notification_outbox where id=notice_id),'wrong lease ignored');
perform public.hd_ack_staff_notification(notice_id,old_token,'retry');
perform pg_temp.check_ok((select status='pending' and next_attempt_at>clock_timestamp() from hunkart_dispatch.staff_notification_outbox where id=notice_id),'retry backoff');
perform pg_temp.check_ok(jsonb_array_length(public.hd_claim_staff_notifications())=0,'immediate retry blocked');
update hunkart_dispatch.staff_notification_outbox set next_attempt_at=clock_timestamp()-interval '1 second' where id=notice_id;
r:=public.hd_claim_staff_notifications();
perform public.hd_ack_staff_notification(notice_id,old_token,'sent');
perform pg_temp.check_ok((select status='sending' and lease_token<>old_token from hunkart_dispatch.staff_notification_outbox where id=notice_id),'old lease cannot acknowledge retry');
perform set_config('request.jwt.claims','{}',true);
r:=public.hd_accept_shop_order(oid);perform pg_temp.check_ok(r->>'ok'='true','keeper acceptance');
perform pg_temp.check_ok(not hunkart_dispatch.staff_notice_eligible(notice_id),'accepted order invalidates shop alert');
 r:=public.hd_accept_shop_order(oid);perform pg_temp.check_ok(r->>'already_accepted'='true','acceptance idempotence');
 perform pg_temp.check_ok((select status='confirmed' from public.orders where id=oid),'customer order confirmed');
 perform pg_temp.check_ok((select count(*)=1 from hunkart_dispatch.notification_outbox where order_id=oid and event_name='order_confirmed'),'one durable confirmation notification');
 perform pg_temp.check_ok(public.hd_can_notify(oid),'keeper can request stored notification');
 perform set_config('request.jwt.claims','{"role":"authenticated"}',true);
 perform pg_temp.denied(format('select public.hd_claim_notifications(%L)',oid),'non-service worker cannot claim notification');
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 r:=public.hd_claim_notifications(oid);notice_id:=(r->0->>'id')::uuid;old_token:=(r->0->>'lease_token')::uuid;
 perform pg_temp.check_ok(jsonb_array_length(r)=1,'service worker claims one notification');
 perform pg_temp.check_ok(jsonb_array_length(public.hd_claim_notifications(oid))=0,'active notification lease prevents duplicate claim');
 perform public.hd_ack_notification(notice_id,gen_random_uuid(),'sent');
 perform pg_temp.check_ok((select status='sending' from hunkart_dispatch.notification_outbox where id=notice_id),'wrong notification lease cannot acknowledge');
 perform public.hd_ack_notification(notice_id,old_token,'retry','Synthetic timeout');
 r:=public.hd_claim_notifications(oid);
 perform public.hd_ack_notification(notice_id,old_token,'sent');
 perform pg_temp.check_ok((select status='sending' from hunkart_dispatch.notification_outbox where id=notice_id),'stale notification lease cannot acknowledge new attempt');
 perform public.hd_ack_notification(notice_id,(r->0->>'lease_token')::uuid,'sent');
 perform pg_temp.check_ok((select status='sent' and attempts=2 from hunkart_dispatch.notification_outbox where id=notice_id),'retried notification records acknowledgement');
 perform set_config('request.jwt.claims','{}',true);

 perform pg_temp.denied(format($q$select public.hd_set_shop_stage(%L,'packed')$q$,oid),'packing cannot skip preparation');
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform pg_temp.check_ok(public.hd_staff_profile('rider')->>'id'=rid::text,'rider own profile');
 perform pg_temp.check_ok(public.hd_staff_profile('keeper') is null,'rider cannot read keeper profile');
 perform public.hd_heartbeat(true,21.9101,85.2301);
 perform set_config('request.jwt.claim.sub',b::text,true);
 perform public.hd_heartbeat(true,21.92,85.24);
 perform hunkart_dispatch.tick();
 select id into f from hunkart_dispatch.offers where order_id=oid and status='pending';
 perform pg_temp.check_ok(f is not null,'worker created request');
perform hunkart_dispatch.enqueue_staff_notifications();
perform pg_temp.check_ok((select count(*)=1 from hunkart_dispatch.staff_notification_outbox where offer_id=f and recipient_id=a),'selected rider gets offer');
perform pg_temp.check_ok(not exists(select 1 from hunkart_dispatch.staff_notification_outbox where offer_id=f and recipient_id<>a),'other riders excluded');
 perform pg_temp.denied(format('select public.hd_respond_offer(%L,true)',f),'wrong rider denied');
 perform set_config('request.jwt.claim.sub',a::text,true);
 r:=public.hd_my_offers();perform pg_temp.check_ok(jsonb_array_length(r)=1 and not (r->0?'phone') and not (r->0?'address'),'offer privacy');
 perform public.hd_respond_offer(f,false);
perform pg_temp.check_ok(not exists(select 1 from hunkart_dispatch.staff_notification_outbox n where offer_id=f and hunkart_dispatch.staff_notice_eligible(n.id)),'declined alert invalid');
 perform hunkart_dispatch.tick();
 select id into f from hunkart_dispatch.offers where order_id=oid and status='pending';
 perform pg_temp.check_ok((select rider_id=rid2 from hunkart_dispatch.offers where id=f),'decline fallback to next rider');
perform hunkart_dispatch.enqueue_staff_notifications();
perform pg_temp.check_ok((select count(*)=1 from hunkart_dispatch.staff_notification_outbox where offer_id=f and recipient_id=b),'next rider gets alert');
 perform set_config('request.jwt.claim.sub',b::text,true);
 perform public.hd_respond_offer(f,true);
perform pg_temp.check_ok(not exists(select 1 from hunkart_dispatch.staff_notification_outbox n where offer_id=f and hunkart_dispatch.staff_notice_eligible(n.id)),'accepted offer alert invalid');
 perform pg_temp.check_ok((select delivery_boy_id=rid2 from public.delivery_tracking where order_id=oid),'accepted assignment');
 perform pg_temp.check_ok(jsonb_array_length(public.hd_my_deliveries())=1,'assigned rider sees own delivery');
 r:=public.hd_respond_offer(f,true);perform pg_temp.check_ok(r->>'already_accepted'='true','rider accept idempotence');
 perform pg_temp.denied(format('select public.hd_start_delivery(%L,21.91,85.23,10)',oid),'pickup blocked before packed');
 perform set_config('request.jwt.claim.sub',k::text,true);
 perform public.hd_set_shop_stage(oid,'preparing');perform public.hd_set_shop_stage(oid,'ready');perform public.hd_set_shop_stage(oid,'packed');
 perform pg_temp.check_ok((select status='packed' from public.orders where id=oid),'preparation sequence completes');
 perform set_config('request.jwt.claim.sub',b::text,true);
 perform public.hd_start_delivery(oid,21.91,85.23,10);
 perform pg_temp.check_ok((select status='out_for_delivery' from public.delivery_tracking where order_id=oid),'packed pickup allowed');
 perform set_config('request.jwt.claim.sub',k::text,true);
 perform pg_temp.denied(format('select public.hd_reject_shop_order(%L,%L)',oid2,'Bad reason'),'invalid rejection reason blocked');
 r:=public.hd_reject_shop_order(oid2,'Item unavailable');
 perform pg_temp.check_ok(r->>'refund_status'='queued','rejection queues refund');
 perform pg_temp.check_ok((select status='cancelled' and payment_status='paid' from public.orders where id=oid2),'cancelled not falsely refunded');
 perform pg_temp.check_ok((select count(*)=1 from hunkart_cancel.refunds where order_id=oid2 and status='queued'),'one refund intent');
 perform pg_temp.denied(format('select public.hd_reject_shop_order(%L,%L)',oid2,'Item unavailable'),'duplicate rejection blocked');
 perform pg_temp.check_ok((select count(*)=1 from hunkart_dispatch.notification_outbox where order_id=oid2 and event_name='shop_rejected'),'rejection notification queued');
 insert into public.orders(id,order_number,customer_id,status,payment_status,payment_id,subtotal,total,shop_id,customer_name,phone,address,area,created_at) values(oid3,'HD-EXPIRY-'||oid3,c,'new','paid','pay_SyntheticC',100,100,sid,'Synthetic customer','0000000000','Synthetic address','Synthetic area',now()-interval '5 minutes');
 insert into public.order_items(order_id,product_id,product_name,variant,variant_label,qty,unit_price,line_total) values(oid3,pid,'Synthetic item','full','Full',1,100,100);
 perform public.hd_accept_shop_order(oid3);
 perform hunkart_dispatch.tick();
 select id into f from hunkart_dispatch.offers where order_id=oid3 and status='pending';
 perform pg_temp.check_ok((select rider_id=rid from hunkart_dispatch.offers where id=f),'busy partner excluded from new offers');
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform pg_temp.check_ok(jsonb_array_length(public.hd_my_deliveries())=0,'other rider cannot read assigned delivery');
 update hunkart_dispatch.offers set expires_at=clock_timestamp()-interval '1 second' where id=f;
 perform pg_temp.denied(format('select public.hd_respond_offer(%L,true)',f),'expired request cannot be accepted');
 perform hunkart_dispatch.tick();
 perform pg_temp.check_ok((select status='expired' from hunkart_dispatch.offers where id=f),'worker expires request');
 perform pg_temp.check_ok(not exists(select 1 from hunkart_dispatch.offers where order_id=oid3 and status='pending'),'busy rider not used as expiry fallback');
 update hunkart_dispatch.jobs set created_at=clock_timestamp()-interval '6 minutes' where order_id=oid3;
 perform hunkart_dispatch.tick();
 perform pg_temp.check_ok((select state='attention' from hunkart_dispatch.jobs where order_id=oid3),'no rider escalates to admin after deadline');
 perform pg_temp.check_ok(not has_function_privilege('anon','public.hd_accept_shop_order(uuid)','execute') and not has_function_privilege('anon','public.hd_respond_offer(uuid,boolean)','execute'),'anonymous RPC access revoked');
 perform pg_temp.check_ok(not has_table_privilege('authenticated','hunkart_dispatch.offers','select'),'direct offer table access denied');
 perform set_config('request.jwt.claim.sub',b::text,true);
 update public.orders set delivery_lat=21.91,delivery_lng=85.23 where id=oid;
 r:=public.delivery_update_location(oid,21.91,85.23,10);
 perform pg_temp.check_ok(r->>'success'='true','legacy GPS update works with new dispatch');
 r:=public.delivery_mark_reached(oid,22.0,85.23,10);
 perform pg_temp.check_ok(r->>'status'='too_far','Reached rejects distant rider');
 r:=public.delivery_mark_reached(oid,21.91,85.23,10);
 perform pg_temp.check_ok(r->>'success'='true','Reached at customer location');
 r:=public.delivery_issue_otp(oid);
 perform pg_temp.check_ok(r->>'status'='otp_ready' and not (r?'otp_code'),'OTP generated without returning secret to rider');
 r:=public.delivery_verify_otp_and_mark_delivered(oid,'INVALID',21.91,85.23,10);
 perform pg_temp.check_ok(r->>'status'='incorrect_otp','wrong delivery OTP denied');
 perform pg_temp.check_ok((select status='out_for_delivery' from public.orders where id=oid),'wrong OTP preserves undelivered state');
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform pg_temp.denied(format('select public.delivery_issue_otp(%L)',oid),'other rider cannot issue OTP');
 perform set_config('request.jwt.claim.sub',b::text,true);
 r:=public.delivery_verify_otp_and_mark_delivered(oid,(select otp_code from public.delivery_otp_codes where order_id=oid),21.91,85.23,10);
 perform pg_temp.check_ok(r->>'success'='true' and r->>'otp_verified'='true','correct OTP completes new dispatch delivery');
 perform pg_temp.check_ok((select status='delivered' from public.orders where id=oid) and (select status='delivered' from public.delivery_tracking where order_id=oid),'order and tracking delivered together');
 perform pg_temp.check_ok((select verified_at is not null and attempt_count=1 from public.delivery_otp_codes where order_id=oid),'OTP verification and wrong attempt audited');
 perform pg_temp.denied(format('select public.delivery_verify_otp_and_mark_delivered(%L,%L,21.91,85.23,10)',oid,'0000'),'completed delivery cannot be repeated');

 perform set_config('request.jwt.claim.sub',k::text,true);
 perform pg_temp.check_ok(public.hd_save_staff_push_subscription('shopkeeper','https://fcm.googleapis.com/fcm/send/hd-test-'||k,repeat('A',87),repeat('B',22),'Synthetic test'),'keeper can save own subscription');
 perform pg_temp.check_ok(public.hd_save_staff_push_subscription('shopkeeper','https://fcm.googleapis.com/fcm/send/hd-test-'||k,repeat('A',87),repeat('B',22),'Synthetic update'),'subscription save idempotent');
 perform pg_temp.check_ok((select count(*)=1 from public.staff_push_subscriptions where user_id=k),'subscription not duplicated');
 perform pg_temp.denied($q$select public.hd_save_staff_push_subscription('delivery_boy','https://fcm.googleapis.com/test',repeat('A',87),repeat('B',22))$q$,'keeper cannot claim rider role');
 perform pg_temp.denied($q$select public.hd_save_staff_push_subscription('shopkeeper','https://attacker.example/test',repeat('A',87),repeat('B',22))$q$,'untrusted push host rejected');
 perform pg_temp.denied($q$select public.hd_save_staff_push_subscription('shopkeeper','https://fcm.googleapis.com/test','bad','bad')$q$,'invalid subscription keys rejected');
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform pg_temp.denied(format($q$select public.hd_save_staff_push_subscription('delivery_boy',%L,repeat('A',87),repeat('B',22))$q$,'https://fcm.googleapis.com/fcm/send/hd-test-'||k),'another staff account cannot take subscription');
 perform pg_temp.check_ok(public.hd_save_staff_push_subscription('delivery_boy','https://fcm.googleapis.com/fcm/send/hd-test-'||a,repeat('A',87),repeat('B',22)),'rider can save own subscription');
 perform set_config('request.jwt.claim.sub',c::text,true);
 perform pg_temp.denied($q$select public.hd_save_staff_push_subscription('shopkeeper','https://fcm.googleapis.com/test',repeat('A',87),repeat('B',22))$q$,'customer cannot register staff push');
 perform pg_temp.check_ok(not has_function_privilege('anon','public.hd_save_staff_push_subscription(text,text,text,text,text)','execute'),'anonymous subscription RPC denied');

end $$;
select count(*) as passed_assertions,jsonb_agg(name) as checks from hd_test_results;

ROLLBACK;
